// Music — playback: queue, shuffle, repeat, fades.
// (Part of one script: the files listed under entry.script run in order and share a scope.)

// ---------------------------------------------------------------- playback
function shuffled(ids) {
  const list = [...ids];
  for (let i = list.length - 1; i > 0; i -= 1) { const j = Math.floor(Math.random() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
  return list;
}
// Pausing and resuming fade over this long when the user switched that on; songs blend
// into each other over library.crossfade seconds (0: they simply follow one another).
const FADE_SECONDS = 0.45;
const crossfadeSeconds = () => Math.max(0, Math.min(12, Number(library.crossfade) || 0));
async function load({ from = null } = {}) {
  const song = currentSong();
  if (!song) return;
  // A picture cannot be blended, so videos start and end with a cut.
  const crossfade = from && !from.video && !song.video ? crossfadeSeconds() : 0;
  player.crossing = false;
  player.time = 0; player.duration = song.duration || 0; player.paused = false;
  library.history = [song.id, ...library.history.filter((id) => id !== song.id)].slice(0, 60);
  song.lastPlayed = Date.now();
  save();
  render();
  try {
    // Subtitles: the tracks inside the video come first, then the files added for this song.
    await macos.audio.load(song.fileId, { crossfade, subtitles: song.subtitleFiles || [], subtitle: song.subtitleOff ? -1 : song.subtitleIndex ?? 0 });
    macos.audio.setMetadata({ title: song.title, artist: song.artist || '', album: song.album || '', artwork: song.artId ? `blob:${song.artId}` : '' }).catch(() => {});
  } catch (error) { player.paused = true; render(); await macos.dialog.alert(String(error?.message || error), { title: song.title }); }
}
// Start playing `ids`. With shuffle on, the chosen song (if any) comes first and the
// rest follow in random order; the original order is kept so shuffle can be undone.
function playSongs(ids, startId = '') {
  if (!ids.length) return;
  player.original = [...ids];
  if (library.shuffle) {
    const first = startId || ids[Math.floor(Math.random() * ids.length)];
    player.queue = [first, ...shuffled(ids.filter((id) => id !== first))];
    player.index = 0;
  } else { player.queue = [...ids]; player.index = Math.max(0, ids.indexOf(startId)); }
  load();
}
function setShuffle(on) {
  library.shuffle = on;
  const current = player.queue[player.index];
  if (current) {
    if (on) { const rest = player.queue.slice(player.index + 1); player.queue = [...player.queue.slice(0, player.index + 1), ...shuffled(rest)]; }
    else if (player.original.includes(current)) { player.queue = [...player.original]; player.index = player.original.indexOf(current); }
  }
  save(); render();
}
function next({ auto = false } = {}) {
  if (!player.queue.length) return;
  const from = player.paused ? null : currentSong();
  if (auto && library.repeat === 'one') return load({ from });
  if (player.index < player.queue.length - 1) { player.index += 1; return load({ from }); }
  if (library.repeat === 'all' || !auto) {
    if (library.shuffle) player.queue = shuffled(player.queue);
    player.index = 0;
    return load({ from });
  }
  player.paused = true; player.time = 0; render();
}
function previous() {
  if (!player.queue.length) return;
  if (player.time > 3) return macos.audio.seek(0);
  const from = player.paused ? null : currentSong();
  player.index = (player.index - 1 + player.queue.length) % player.queue.length;
  load({ from });
}
async function toggle() {
  if (!currentSong()) return playSongs((isDetail() ? visibleSongs() : allSongs()).map((song) => song.id));
  const fade = library.fade ? FADE_SECONDS : 0;
  if (player.paused) await macos.audio.play({ fade }); else await macos.audio.pause({ fade });
}
async function stop() {
  await macos.audio.stop().catch(() => {});
  player = { original: [], queue: [], index: -1, paused: true, time: 0, duration: 0, subtitles: [], subtitle: -1 };
}
function enqueue(ids, { nextUp = false } = {}) {
  if (!currentSong()) return playSongs(ids);
  if (nextUp) player.queue.splice(player.index + 1, 0, ...ids); else player.queue.push(...ids);
  player.original.push(...ids.filter((id) => !player.original.includes(id)));
  render();
}

macos.on('audio', (event) => {
  if (event.type === 'action') {
    if (event.action === 'play' || event.action === 'pause') toggle();
    if (event.action === 'nexttrack') next();
    if (event.action === 'previoustrack') previous();
    return;
  }
  if (event.type === 'ended') { const song = currentSong(); if (song) { song.plays = (song.plays || 0) + 1; save(); } next({ auto: true }); return; }
  if (event.type === 'error') { player.paused = true; render(); return; }
  const wasPaused = player.paused;
  if (Array.isArray(event.subtitles)) { player.subtitles = event.subtitles; player.subtitle = event.subtitle; }
  player.paused = event.paused; player.time = event.currentTime; if (event.duration) player.duration = event.duration;
  // With cross-fading on, the next song starts under the end of this one.
  const blend = crossfadeSeconds();
  if (blend && event.type === 'timeupdate' && !event.paused && !player.crossing && event.duration > blend * 2 + 1 && event.duration - event.currentTime <= blend
    && !currentSong()?.video && (player.index < player.queue.length - 1 || library.repeat !== 'off')) {
    player.crossing = true;
    const song = currentSong(); if (song) { song.plays = (song.plays || 0) + 1; save(); }
    next({ auto: true });
    return;
  }
  if (event.type === 'loadedmetadata') {
    const song = currentSong();
    if (song && event.duration && Math.abs((song.duration || 0) - event.duration) > 1) { song.duration = event.duration; save(); }
  }
  // Progress ticks only touch three controls; everything else re-renders through view().
  if (event.type === 'timeupdate' && wasPaused === event.paused) {
    macos.ui.patch('time', { text: clock(player.time) });
    macos.ui.patch('seek', { value: Math.round(player.time), max: Math.max(1, Math.round(player.duration)) });
    macos.ui.patch('duration', { text: clock(player.duration) });
    tickStatusPanel();
  } else render();
});

// The menu bar item: what is playing, with its cover, the transport controls and the place
// in the song — a panel the system draws under the item (statusItem `panel`). A right-click
// opens the short menu instead.
let statusSignature = '';
let statusSecond = -1;
const remaining = () => (player.duration ? `-${clock(Math.max(0, player.duration - player.time))}` : '');
function statusPanel(song) {
  const control = (id, icon, size, disabled) => ({ type: 'button', id, icon: ICON(icon), iconTint: true, iconSize: size, variant: 'plain', shape: 'circle', width: size + 18, height: size + 18, disabled });
  return { type: 'stack', direction: 'horizontal', gap: 14, align: 'center', width: 356, children: [
    { type: 'image', id: 'show', src: artOf(song), width: 116, height: 116, radius: 10, fit: 'cover', tooltip: T('showMusic', 'Show Music') },
    { type: 'stack', direction: 'vertical', gap: 2, grow: 1, minWidth: 0, children: [
      { type: 'text', text: song ? song.title : T('notPlaying', 'Not Playing'), fontSize: 14, fontWeight: 'semibold', lines: 1 },
      { type: 'text', text: song ? [song.artist, song.album].filter(Boolean).join(' — ') || ' ' : ' ', fontSize: 12, color: 'secondary', lines: 1 },
      { type: 'stack', direction: 'horizontal', justify: 'center', align: 'center', gap: 16, margin: [8, 0, 4, 0], children: [
        control('previous', 'previous', 18, !song),
        control('toggle', player.paused || !song ? 'play' : 'pause', 24, false),
        control('next', 'next', 18, !song)
      ] },
      { type: 'slider', id: 'panel-seek', min: 0, max: Math.max(1, Math.round(player.duration)), step: 1, value: Math.round(player.time), disabled: !song },
      { type: 'stack', direction: 'horizontal', children: [
        { type: 'text', id: 'panel-time', text: clock(player.time), fontSize: 11, color: 'secondary', grow: 1 },
        { type: 'text', id: 'panel-left', text: remaining(), fontSize: 11, color: 'secondary' }
      ] }
    ] }
  ] };
}
function updateStatusItem() {
  const song = currentSong();
  const signature = `${song?.id || ''}|${song?.artId || ''}|${library.defaultArtId}|${player.paused}|${Math.round(player.duration)}|${macos.i18n.language()}`;
  if (signature === statusSignature) return;
  statusSignature = signature;
  const line = song ? `${song.title}${song.artist ? ` — ${song.artist}` : ''}` : T('notPlaying', 'Not Playing');
  macos.statusItem.set({
    icon: ICON('nav-songs'), tooltip: line, panel: statusPanel(song),
    items: [
      { id: 'now', label: line, disabled: true },
      { separator: true },
      { id: 'toggle', label: player.paused || !song ? T('play', 'Play') : T('pause', 'Pause') },
      { id: 'next', label: T('menuNext', 'Next'), disabled: !song },
      { id: 'previous', label: T('menuPrevious', 'Previous'), disabled: !song },
      { separator: true },
      { id: 'show', label: T('showMusic', 'Show Music') }
    ]
  }).catch(() => {});
}
// The place in the song, once a second.
function tickStatusPanel() {
  const second = Math.round(player.time);
  if (second === statusSecond) return;
  statusSecond = second;
  macos.statusItem.patch([
    { id: 'panel-seek', props: { value: second, max: Math.max(1, Math.round(player.duration)) } },
    { id: 'panel-time', props: { text: clock(player.time) } },
    { id: 'panel-left', props: { text: remaining() } }
  ]).catch(() => {});
}

src/state.js.text:
// Music — a native-runtime app.
//
// Songs are never loaded into this sandbox. Imported audio files live in the host file
// store (macos.files), which also reads their tags and cover art; this script only keeps
// ids and metadata, and the host plays the audio (macos.audio). The whole interface is
// one function of state, view(), handed to macos.ui.render(), which diffs it against
// what is on screen.

const T = (key, fallback) => macos.i18n.t(key, fallback);
const uid = (prefix) => `${prefix}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
const ICON = (name) => `assets/icons/${name}.svg`;
const DEFAULT_ART = 'assets/cover.svg';

// ---------------------------------------------------------------- state
let library = { songs: {}, playlists: [], folders: [], volume: 0.8, shuffle: false, repeat: 'off', accent: '', defaultArtId: '', history: [], fade: false, crossfade: 0 };
let route = { kind: 'songs', id: '' };       // songs | recent | favorites | albums | artists | playlists | folder | album | artist | playlist
let query = '';
const sorts = {};                            // route key -> { field, descending }
let player = { original: [], queue: [], index: -1, paused: true, time: 0, duration: 0, subtitles: [], subtitle: -1 };
let showQueue = false;
let editing = null;                          // { id, title, artist, album } while the info sheet is open
let settingsOpen = false;
let showNow = false;                         // the full-window Now Playing view
let nowTab = 'queue';                        // queue | history
let importing = null;                        // { done, total } while the host is storing files
let usage = null;                            // { count, bytes } shown in Settings
let storage = null;                          // the Manage Storage sheet: { files: Map(id -> size), filter, sort, selected }
let busy = '';

// The accent is the app's own choice, and its own settings UI. It applies while the
// system accent is "multicolor"; a fixed system accent overrides it.
const ACCENTS = { red: '#ff5257', pink: '#f74f9e', orange: '#f7821b', yellow: '#f5b60a', green: '#62ba46', blue: '#0a84ff', purple: '#a550a7', graphite: '#8c8c8c' };
const DEFAULT_ACCENT = 'red';
let accentSetting = macos.context.accentSetting || 'multicolor';
// Light, dark or following the system: the app's own choice, which the host remembers.
let appearance = macos.context.appearance || 'system';

try {
  const saved = await macos.storage.get('library');
  if (saved && typeof saved === 'object') library = { ...library, ...saved, songs: saved.songs || {}, playlists: saved.playlists || [], folders: saved.folders || [], history: Array.isArray(saved.history) ? saved.history : [] };
} catch {}

let saveTimer = 0;
function save() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => { macos.storage.set('library', library).catch((error) => macos.log('save failed', String(error))); publishSearch(); publishWidgets(); }, 250);
}
// Spotlight finds songs and playlists; choosing one plays the song or opens the playlist
// (the 'search' event).
let searchSignature = '';
function publishSearch() {
  const items = [
    ...Object.values(library.songs).map((song) => ({ id: `song:${song.id}`, title: song.title || '', subtitle: [song.artist, song.album].filter(Boolean).join(' — ') })),
    ...library.playlists.map((item) => ({ id: `playlist:${item.id}`, title: item.name || '', subtitle: T('playlists', 'Playlists') }))
  ].filter((item) => item.title);
  const signature = JSON.stringify(items);
  if (signature === searchSignature) return;
  searchSignature = signature;
  macos.search.setItems(items).catch(() => {});
}

// ---------------------------------------------------------------- selectors
const routeKey = () => `${route.kind}:${route.id}`;
const playlistOf = (id = route.id) => library.playlists.find((item) => item.id === id) || null;
const currentPlaylist = () => (route.kind === 'playlist' ? playlistOf() : null);
const currentSong = () => library.songs[player.queue[player.index]] || null;
// Songs without a cover of their own show the user's default picture, if one was chosen in Settings.
const defaultArt = () => (library.defaultArtId ? `blob:${library.defaultArtId}` : DEFAULT_ART);
const artOf = (song) => (song?.artId ? `blob:${song.artId}` : defaultArt());
const allSongs = () => Object.values(library.songs);
const artistOf = (song) => song.artist || T('unknownArtist', 'Unknown Artist');
const albumOf = (song) => song.album || T('unknownAlbum', 'Unknown Album');
const albumKey = (song) => `${albumOf(song)} ⧸ ${song.albumArtist || artistOf(song)}`;

function clock(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}
function longClock(seconds) {
  const minutes = Math.max(1, Math.round(seconds / 60));
  return minutes >= 60 ? `${Math.floor(minutes / 60)} ${T('hours', 'hr')} ${minutes % 60} ${T('minutes', 'min')}` : `${minutes} ${T('minutes', 'min')}`;
}
const compare = (a, b) => String(a ?? '').localeCompare(String(b ?? ''), undefined, { numeric: true, sensitivity: 'base' });

function albums() {
  const map = new Map();
  for (const song of allSongs()) {
    const key = albumKey(song);
    if (!map.has(key)) map.set(key, { id: key, title: albumOf(song), artist: song.albumArtist || artistOf(song), songs: [] });
    map.get(key).songs.push(song);
  }
  return [...map.values()].sort((a, b) => compare(a.title, b.title));
}
function artists() {
  const map = new Map();
  for (const song of allSongs()) {
    const key = artistOf(song);
    if (!map.has(key)) map.set(key, { id: key, title: key, songs: [] });
    map.get(key).songs.push(song);
  }
  return [...map.values()].sort((a, b) => compare(a.title, b.title));
}
function playlistCover(item) {
  if (item.coverFileId) return `blob:${item.coverFileId}`;
  const first = item.songIds.map((id) => library.songs[id]).find((song) => song?.artId);
  return first ? `blob:${first.artId}` : defaultArt();
}

// Songs of the current detail route, before search / sort.
function baseSongs() {
  if (route.kind === 'playlist') return (playlistOf()?.songIds || []).map((id) => library.songs[id]).filter(Boolean);
  if (route.kind === 'album') return allSongs().filter((song) => albumKey(song) === route.id).sort((a, b) => (Number(a.track) || 999) - (Number(b.track) || 999) || compare(a.title, b.title));
  if (route.kind === 'artist') return allSongs().filter((song) => artistOf(song) === route.id).sort((a, b) => compare(albumOf(a), albumOf(b)) || (Number(a.track) || 999) - (Number(b.track) || 999));
  if (route.kind === 'favorites') return allSongs().filter((song) => song.loved).sort((a, b) => compare(a.title, b.title));
  if (route.kind === 'recent') return allSongs().sort((a, b) => (b.added || 0) - (a.added || 0));
  return allSongs().sort((a, b) => compare(a.title, b.title));
}
function visibleSongs() {
  let list = baseSongs();
  const needle = query.trim().toLocaleLowerCase();
  if (needle) list = list.filter((song) => `${song.title}\n${song.artist}\n${song.album}`.toLocaleLowerCase().includes(needle));
  const sort = sorts[routeKey()];
  if (sort) {
    const value = (song) => (sort.field === 'time' ? song.duration || 0 : sort.field === 'added' ? song.added || 0 : sort.field === 'plays' ? song.plays || 0 : sort.field === 'artist' ? artistOf(song) : sort.field === 'album' ? albumOf(song) : song.title);
    list = [...list].sort((a, b) => (typeof value(a) === 'number' ? value(a) - value(b) : compare(value(a), value(b))));
    if (sort.descending) list.reverse();
  }
  return list;
}
const isDetail = () => !['albums', 'artists', 'playlists', 'folder'].includes(route.kind);
const folderOf = (id = route.id) => library.folders.find((item) => item.id === id) || null;

src/views.js.text:
// Music — the interface: sidebar, lists, player bar, Now Playing, sheets.
// (Part of one script: the files listed under entry.script run in order and share a scope.)

// ---------------------------------------------------------------- view
function iconButton(id, icon, extra = {}) {
  return { type: 'button', id, icon: ICON(icon), iconTint: true, iconSize: 16, variant: 'plain', width: 30, height: 30, shape: 'circle', ...extra };
}

function sidebar() {
  // Library rows neither move nor accept drops; playlists can be dragged, and playlists,
  // folders and “All Playlists” accept them.
  const navItem = (id, title, icon, drop = false) => ({ id, title, icon: ICON(icon), tint: true, drag: false, drop });
  const playlistRow = (item, indent) => ({
    id: `playlist:${item.id}`, title: item.name, icon: playlistCover(item), indent,
    menu: [
      { id: 'play', label: T('play', 'Play') }, { id: 'shuffle', label: T('shuffle', 'Shuffle') }, { separator: true },
      { id: 'rename', label: T('rename', 'Rename…') }, { id: 'move', label: T('moveToFolder', 'Move to Folder…') }, { id: 'export', label: T('exportPlaylist', 'Export Playlist…') },
      { separator: true }, { id: 'delete', label: T('deletePlaylist', 'Delete Playlist'), danger: true }
    ]
  });
  const items = [
    { id: 'h:library', title: T('library', 'Library'), header: true },
    navItem('recent:', T('recentlyAdded', 'Recently Added'), 'nav-recent'), navItem('artists:', T('artists', 'Artists'), 'nav-artists'),
    navItem('albums:', T('albums', 'Albums'), 'nav-albums'), navItem('songs:', T('songs', 'Songs'), 'nav-songs'), navItem('favorites:', T('favorites', 'Favourites'), 'nav-favorites'),
    { id: 'h:playlists', title: T('playlists', 'Playlists'), header: true },
    navItem('playlists:', T('allPlaylists', 'All Playlists'), 'nav-playlists', true)
  ];
  for (const folder of library.folders) {
    items.push({ id: `folder:${folder.id}`, title: folder.name, icon: ICON('nav-folder'), tint: true, disclosure: folder.collapsed ? 'closed' : 'open', drag: false,
      menu: [{ id: 'new-in-folder', label: T('newPlaylist', 'New Playlist') }, { id: 'rename-folder', label: T('rename', 'Rename…') }, { separator: true }, { id: 'delete-folder', label: T('deleteFolder', 'Delete Folder'), danger: true }] });
    if (!folder.collapsed) library.playlists.filter((item) => item.folderId === folder.id).forEach((item) => items.push(playlistRow(item, 1)));
  }
  library.playlists.filter((item) => !library.folders.some((folder) => folder.id === item.folderId)).forEach((item) => items.push(playlistRow(item, 0)));
  const selectedRow = ['album', 'artist'].includes(route.kind) ? `${route.kind}s:` : routeKey();
  return { type: 'stack', id: 'sidebar', direction: 'vertical', gap: 6, width: 214, padding: [8, 8, 10, 10], children: [
    { type: 'list', id: 'nav', grow: 1, plain: true, value: selectedRow, rowHeight: 30, iconSize: 20, draggable: true, dropTarget: true, items },
    ...(importing ? [{ type: 'stack', id: 'import-status', direction: 'vertical', gap: 5, padding: [2, 4, 4, 4], children: [
      { type: 'text', id: 'import-label', variant: 'caption', lines: 1, text: importLabel() },
      { type: 'progress', id: 'import-progress', value: importing.done, max: Math.max(1, importing.total) }
    ] }] : []),
    { type: 'stack', direction: 'horizontal', gap: 6, children: [
      { type: 'button', id: 'add-menu', label: T('new', 'New'), icon: ICON('plus'), iconTint: true, iconSize: 13, variant: 'tinted', grow: 1 },
      { type: 'button', id: 'import-songs', label: T('import', 'Import'), variant: 'plain', grow: 1 }
    ] }
  ] };
}

const importLabel = () => (importing?.exporting ? T('exportingProgress', 'Exporting {done} of {total}…') : T('importingProgress', 'Importing {done} of {total}…')).replace('{done}', String(importing?.done ?? 0)).replace('{total}', String(importing?.total ?? 0));

function collectionView() {
  const rows = route.kind === 'albums'
    ? albums().map((album) => ({ id: album.id, title: album.title, subtitle: `${album.artist} · ${album.songs.length} ${T('songsCount', 'songs')}`, icon: artOf(album.songs.find((song) => song.artId)) }))
    : route.kind === 'artists'
      ? artists().map((artist) => ({ id: artist.id, title: artist.title, subtitle: `${artist.songs.length} ${T('songsCount', 'songs')}`, icon: artOf(artist.songs.find((song) => song.artId)) }))
      : library.playlists.filter((item) => route.kind !== 'folder' || item.folderId === route.id).map((item) => ({ id: item.id, title: item.name, subtitle: `${item.songIds.filter((id) => library.songs[id]).length} ${T('songsCount', 'songs')}${library.folders.find((folder) => folder.id === item.folderId) ? ` · ${library.folders.find((folder) => folder.id === item.folderId).name}` : ''}`, icon: playlistCover(item) }));
  const needle = query.trim().toLocaleLowerCase();
  const filtered = needle ? rows.filter((row) => `${row.title}\n${row.subtitle}`.toLocaleLowerCase().includes(needle)) : rows;
  const title = route.kind === 'albums' ? T('albums', 'Albums') : route.kind === 'artists' ? T('artists', 'Artists') : route.kind === 'folder' ? (folderOf()?.name || '') : T('allPlaylists', 'All Playlists');
  return [
    { type: 'stack', id: 'collection-header', direction: 'horizontal', align: 'center', gap: 10, padding: [16, 18, 10, 20], ...bar(BAR.collection), children: [
      { type: 'text', id: 'collection-title', text: title, fontSize: 26, fontWeight: 'bold', grow: 1 },
      { type: 'input', id: 'search', inputType: 'search', value: query, placeholder: T('search', 'Search'), width: 190 }
    ] },
    { type: 'list', id: 'collection', grow: 1, plain: true, rowHeight: 60, iconSize: 46, margin: [0, 10, 0, 10], insetTop: BAR.collection, insetBottom: 86, items: filtered,
      placeholder: route.kind === 'folder' ? T('emptyFolder', 'This folder is empty. Drag playlists onto it in the sidebar.') : route.kind === 'playlists' ? T('noPlaylists', 'No playlists yet. Use “New” to create one.') : T('emptyHint', 'Drop audio files here, or choose “Import”.') }
  ];
}

// The header of a page is a frosted bar floating over its list (material: "bar"): the
// rows scroll underneath it, and the list leaves that much room above its first row.
const BAR = { collection: 62, plain: 112, cover: 180 };
const bar = (height) => ({ height, material: 'bar', alignSelf: 'start', justifySelf: 'stretch' });
function detailView() {
  const list = currentPlaylist();
  const songs = visibleSongs();
  const playing = currentSong();
  const total = songs.reduce((sum, song) => sum + (song.duration || 0), 0);
  const sort = sorts[routeKey()];
  const titles = { songs: T('songs', 'Songs'), recent: T('recentlyAdded', 'Recently Added'), favorites: T('favorites', 'Favourites') };
  const title = list ? list.name : route.kind === 'album' ? route.id.split(' ⧸ ')[0] : route.kind === 'artist' ? route.id : titles[route.kind];
  const subtitle = route.kind === 'album' ? route.id.split(' ⧸ ')[1] : '';
  const cover = list ? playlistCover(list) : (route.kind === 'album' || route.kind === 'artist') ? artOf(baseSongs().find((song) => song.artId)) : '';
  const meta = busy || `${songs.length} ${T('songsCount', 'songs')}${songs.length ? ` · ${longClock(total)}` : ''}`;
  const manualOrder = Boolean(list) && !sort && !query.trim();
  const songMenu = [
    { id: 'play', label: T('play', 'Play') }, { id: 'play-next', label: T('playNext', 'Play Next') }, { id: 'queue', label: T('addToQueue', 'Add to Queue') }, { separator: true },
    { id: 'add-to', label: T('addToPlaylist', 'Add to Playlist…') }, { id: 'love', label: T('toggleFavourite', 'Favourite / Unfavourite') }, { id: 'info', label: T('getInfo', 'Get Info…') }, { id: 'export-song', label: T('exportSong', 'Export Song…') }, { separator: true },
    ...(list ? [{ id: 'remove', label: T('removeFromPlaylist', 'Remove from Playlist') }] : []),
    { id: 'delete', label: T('deleteFromLibrary', 'Delete from Library'), danger: true }
  ];
  const actions = { type: 'stack', direction: 'horizontal', gap: 8, align: 'center', children: [
    iconButton('shuffle-all', 'shuffle', { variant: undefined, background: 'fill', color: 'accent', width: 34, height: 34, disabled: !songs.length, tooltip: T('shuffle', 'Shuffle') }),
    { type: 'button', id: 'play-all', label: T('play', 'Play'), icon: ICON('play'), iconTint: true, iconSize: 12, shape: 'pill', background: 'fill', color: 'accent', fontWeight: 'semibold', height: 34, minWidth: 110, disabled: !songs.length },
    iconButton('more', 'ellipsis', { variant: undefined, background: 'fill', width: 34, height: 34, tooltip: T('more', 'More') })
  ] };
  const tools = { type: 'stack', id: 'tools', direction: 'horizontal', gap: 6, align: 'center', children: [
    iconButton('sort', 'sort', { tooltip: T('sort', 'Sort'), color: sort ? 'accent' : undefined }),
    { type: 'input', id: 'search', inputType: 'search', value: query, placeholder: list ? T('findInPlaylist', 'Find in Playlist') : T('search', 'Search'), width: 190 }
  ] };
  const heading = list
    ? { type: 'input', id: 'title', value: list.name, placeholder: T('playlistName', 'Playlist name'), fontSize: 26, fontWeight: 'bold', maxLength: 80, background: 'clear', border: 'clear' }
    : { type: 'text', id: 'title-static', text: title, fontSize: 26, fontWeight: 'bold', lines: 1 };
  const header = cover
    ? { type: 'stack', id: 'header', direction: 'horizontal', gap: 20, align: 'end', padding: [14, 18, 14, 20], ...bar(BAR.cover), children: [
      { type: 'image', id: 'cover', src: cover, width: 150, height: 150, radius: 12, fit: 'cover', tooltip: list ? T('coverHint', 'Click or drop an image to change the cover') : '' },
      // The column is as tall as the cover: search at its top, the title block at its bottom.
      // (Sized by its content and bottom-aligned, it grew out of the top of the bar.)
      { type: 'stack', direction: 'vertical', gap: 5, grow: 1, minWidth: 0, alignSelf: 'stretch', children: [
        { type: 'stack', direction: 'horizontal', justify: 'end', children: [tools] },
        { type: 'spacer', grow: 1 },
        heading,
        ...(subtitle ? [{ type: 'text', id: 'subtitle', text: subtitle, fontSize: 17, color: 'accent', lines: 1 }] : []),
        { type: 'text', id: 'meta', variant: 'muted', lines: 1, text: meta },
        actions
      ] }
    ] }
    : { type: 'stack', id: 'header', direction: 'vertical', gap: 8, padding: [16, 18, 12, 20], ...bar(BAR.plain), children: [
      { type: 'stack', direction: 'horizontal', align: 'center', gap: 10, children: [{ ...heading, grow: 1 }, tools] },
      { type: 'stack', direction: 'horizontal', align: 'center', gap: 12, children: [actions, { type: 'text', id: 'meta', variant: 'muted', lines: 1, text: meta, grow: 1 }] }
    ] };
  return [
    header,
    { type: 'list', id: 'songs', grow: 1, plain: true, multiple: true, reorderable: manualOrder, draggable: true, rowHeight: 52, iconSize: 40, margin: [0, 10, 0, 10], insetTop: cover ? BAR.cover : BAR.plain, insetBottom: 86,
      placeholder: query.trim() ? T('noResults', 'No results') : T('emptyHint', 'Drop audio files here, or choose “Import”.'),
      items: songs.map((song) => ({ id: song.id, icon: artOf(song), title: song.title, subtitle: [song.artist, song.album].filter(Boolean).join(' — ') || T('unknownArtist', 'Unknown Artist'),
        detail: `${song.loved ? '♥  ' : ''}${song.duration ? clock(song.duration) : ''}`, emphasis: playing?.id === song.id })),
      itemMenu: songMenu }
  ];
}

const loveButton = (song, iconSize, size) => ({ type: 'button', id: 'love-now', icon: ICON(song.loved ? 'star-fill' : 'star'), iconTint: true, iconSize, shape: 'circle', variant: 'plain', width: size, height: size,
  color: song.loved ? 'accent' : 'secondary', showOnHover: !song.loved, tooltip: T('toggleFavourite', 'Favourite / Unfavourite') });

function playerBar() {
  const playing = currentSong();
  const repeatIcon = library.repeat === 'one' ? 'repeat-one' : 'repeat';
  // Playback controls and the timeline keep their order in a right-to-left layout.
  return { type: 'stack', id: 'player', ltr: true, direction: 'horizontal', gap: 8, align: 'center', padding: [8, 14, 8, 12], margin: [0, 14, 12, 14], radius: 16, material: 'glass', alignSelf: 'end', justifySelf: 'stretch', children: [
    iconButton('toggle-shuffle', 'shuffle', { color: library.shuffle ? 'accent' : 'secondary', tooltip: T('shuffle', 'Shuffle') }),
    iconButton('prev', 'previous', { disabled: !playing, iconSize: 18 }),
    iconButton('toggle', player.paused ? 'play' : 'pause', { iconSize: 20, width: 36, height: 36, disabled: !playing && !allSongs().length }),
    iconButton('next', 'next', { disabled: !playing, iconSize: 18 }),
    iconButton('toggle-repeat', repeatIcon, { color: library.repeat === 'off' ? 'secondary' : 'accent', tooltip: T('repeat', 'Repeat') }),
    // Pointing at the cover offers the full-window Now Playing view.
    { type: 'zstack', id: 'now-art-wrap', width: 38, height: 38, margin: [0, 2, 0, 6], children: [
      { type: 'image', id: 'now-art', src: artOf(playing), width: 38, height: 38, radius: 6, fit: 'cover' },
      ...(playing ? [{ type: 'button', id: 'open-now', icon: ICON('expand'), iconTint: true, iconSize: 16, shape: 'circle', width: 38, height: 38, radius: 6, background: 'rgba(0,0,0,0.5)', color: 'white', showOnHover: true, tooltip: showNow ? T('closeNowPlaying', 'Back') : T('nowPlaying', 'Now Playing') }] : [])
    ] },
    { type: 'stack', direction: 'vertical', gap: 1, grow: 1, minWidth: 0, children: [
      // The star appears while the pointer is on the title row; a favourite keeps it lit.
      { type: 'stack', id: 'now-row', direction: 'horizontal', gap: 3, align: 'center', minWidth: 0, children: [
        { type: 'text', id: 'now', lines: 1, fontSize: 12.5, fontWeight: 'semibold', text: playing ? playing.title : T('notPlaying', 'Not Playing') },
        ...(playing ? [loveButton(playing, 13, 18)] : [])
      ] },
      { type: 'text', id: 'now-artist', lines: 1, fontSize: 11, color: 'secondary', text: playing ? [playing.artist, playing.album].filter(Boolean).join(' — ') : '' },
      { type: 'stack', direction: 'horizontal', gap: 8, align: 'center', children: [
        { type: 'text', id: 'time', text: clock(player.time), fontSize: 10, color: 'secondary', width: 30, textAlign: 'end' },
        { type: 'slider', id: 'seek', grow: 1, min: 0, max: Math.max(1, Math.round(player.duration)), step: 1, value: Math.round(player.time), disabled: !playing },
        { type: 'text', id: 'duration', text: clock(player.duration), fontSize: 10, color: 'secondary', width: 30 }
      ] }
    ] },
